const User = require('./User');  // Import the User class

class UsersList {
    
    constructor() {
        this.users = [User = new User('John', 'Doe', 'user1', 'pass1', 'male', 'picture.jpg')];
    }

    getUsers() {
        return this.users.map(user => new User(user.firstName, user.lastName, user.email, user.password, user.gender, user.picture));
    }

    addUser(user) {
        this.users.push(user);
    }
}

// Export a singleton instance of the UserList class
module.exports = new UsersList();
